contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address target, uint256 freezeValue, uint256 transferValue) public {
        require(target != address(0));
        require(target != address(this));

        c.freezeAccount(target, true); if (__ESBMC_reverted()) return;
        bool frozen = c.frozenAccount(target); if (__ESBMC_reverted()) return;

        uint256 balBefore = c.balanceOf(target); if (__ESBMC_reverted()) return;
        bool reverted;
        c.transfer(target, transferValue); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            frozen &&
            frozen == c.frozenAccount(target) &&
            (reverted ? c.balanceOf(target) == balBefore : c.balanceOf(target) == balBefore + transferValue)
        );
    }
}

